// A-1 の Classifier.js + Routing.js に相当する処理。
// n8n の Code ノードは JS のみ。GAS と同じ言語なので移植は直訳に近い。

const CATEGORIES = ['システム障害', '申請手続き', '備品・設備', 'その他'];
const URGENCIES = ['高', '中', '低'];

// --- Gemini 応答のパース（3段フォールバック） ---
const resp = $('Gemini分類').first().json;
let raw = resp?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
if (!raw) {
  throw new Error('Gemini の応答に本文がありません: ' + JSON.stringify(resp).slice(0, 300));
}
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e1) {
  const unfenced = raw.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '');
  try {
    parsed = JSON.parse(unfenced);
  } catch (e2) {
    const s = unfenced.indexOf('{'), t = unfenced.lastIndexOf('}');
    if (s === -1 || t <= s) throw new Error('分類結果を JSON として解釈できません: ' + raw.slice(0, 200));
    parsed = JSON.parse(unfenced.slice(s, t + 1));
  }
}

// --- 値の検証（モデルは定義外の値を平気で返す） ---
const category = String(parsed?.category ?? '').trim();
const urgency = String(parsed?.urgency ?? '').trim();
if (!CATEGORIES.includes(category)) throw new Error('分類が定義外です: ' + category);
if (!URGENCIES.includes(urgency)) throw new Error('緊急度が定義外です: ' + urgency);

// --- 担当マスタから宛先を解決 ---
const routing = $('担当マスタ').all().map(i => i.json);
const isEmail = v => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v);
const clean = v => String(v ?? '').replace(/[\s\u3000]/g, '');

const hit = routing.find(r => String(r['分類'] ?? '').trim() === category);
let to = hit ? clean(hit['担当者メールアドレス']) : '';
let isFallback = false;

if (!isEmail(to)) {
  // A-1 では PropertiesService の FALLBACK_TO を使った。
  // n8n では担当マスタの「その他」行をフォールバックにする（設定をシートに集約する設計）。
  const fb = routing.find(r => String(r['分類'] ?? '').trim() === 'その他');
  to = fb ? clean(fb['担当者メールアドレス']) : '';
  isFallback = true;
  if (!isEmail(to)) throw new Error('分類「' + category + '」の担当者も、フォールバック（その他）も未設定です。');
}

// --- 元の問い合わせ ---
const src = $('フォーム回答トリガー').first().json;

return [{
  json: {
    rowNumber: src.row_number,
    name: String(src['お名前'] ?? '').trim(),
    email: String(src['メールアドレス'] ?? '').trim(),
    body: String(src['問い合わせ内容'] ?? '').trim(),
    category,
    urgency,
    reason: String(parsed?.reason ?? '').trim(),
    to,
    status: isFallback ? '未分類' : '完了',
    detail: isFallback ? '担当者未設定のためフォールバック送信。判断理由: ' + (parsed?.reason ?? '') : String(parsed?.reason ?? ''),
  },
}];

